import re,zlib
from pathlib import Path
pdf=Path('/paper/Forward_Projection_Paper.pdf').read_bytes()
streams=[]
for m in re.finditer(rb'stream\r?\n', pdf):
    start=m.end(); end=pdf.find(b'endstream', start)
    if end<0: continue
    data=pdf[start:end].strip(b'\r\n')
    dict_start=pdf.rfind(b'<<', 0, m.start())
    d=b''
    if dict_start!=-1:
        dict_end=pdf.find(b'>>', dict_start, m.start()+2000)
        if dict_end!=-1 and dict_end<m.start(): d=pdf[dict_start:dict_end+2]
    out=None
    if b'FlateDecode' in d:
        try: out=zlib.decompress(data)
        except Exception:
            try: out=zlib.decompress(data, -15)
            except Exception: out=None
    else: out=data
    if out is not None:
        streams.append((d,out))

def parse_pdf_string(data, i):
    assert data[i] == 40
    i += 1
    out = bytearray()
    depth = 1
    while i < len(data) and depth:
        c = data[i]
        if c == 92:  # backslash
            i += 1
            if i >= len(data): break
            c = data[i]
            if c in b'nrtbf':
                out.extend({ord('n'):b'\n', ord('r'):b'\r', ord('t'):b'\t', ord('b'):b'\b', ord('f'):b'\f'}[c])
                i += 1
            elif c in b'()\\':
                out.append(c); i += 1
            elif 48 <= c <= 55:
                octal = bytes([c]); i += 1
                for _ in range(2):
                    if i < len(data) and 48 <= data[i] <= 55:
                        octal += bytes([data[i]]); i += 1
                    else:
                        break
                out.append(int(octal, 8) & 0xff)
            elif c in b'\r\n':
                # line continuation
                if c == 13 and i+1 < len(data) and data[i+1] == 10: i += 2
                else: i += 1
            else:
                out.append(c); i += 1
        elif c == 40:
            depth += 1; out.append(c); i += 1
        elif c == 41:
            depth -= 1
            if depth:
                out.append(c)
            i += 1
        else:
            out.append(c); i += 1
    return bytes(out), i

def extract_text(data):
    parts=[]; i=0
    while i < len(data):
        c=data[i]
        if c == 40:
            s,j=parse_pdf_string(data,i)
            # Check after string-ish if followed eventually by Tj/TJ or in array. We'll include all strings.
            try:
                txt=s.decode('latin1')
            except:
                txt=str(s)
            parts.append(txt)
            i=j
        elif data.startswith(b'T*', i) or data.startswith(b'TD', i) or data.startswith(b'Td', i) or data.startswith(b'ET', i):
            parts.append('\n')
            i += 2
        else:
            i += 1
    # crude join: concatenate chars; replace nulls/control weird
    text=''.join(parts)
    # map control chars from common glyphs if obvious
    replacements={
        '\x01':'fi','\x02':'fl','\x03':'ff','\x04':'ffi','\x05':'ffl',
        '\x06':'–','\x07':'—','\x08':'“','\x09':'”','\x0b':' ',
    }
    for k,v in replacements.items(): text=text.replace(k,v)
    text=re.sub(r'[\x00-\x08\x0c-\x1f]', '', text)
    text=re.sub(r' +',' ', text)
    text=re.sub(r'\n{3,}','\n\n', text)
    return text

for si in range(38,49):
    if si >= len(streams): continue
    d,out=streams[si]
    score=sum(out.count(tok) for tok in [b'Tj',b'TJ'])
    if score<20: continue
    text=extract_text(out)
    print('\n===== STREAM',si,'LEN',len(text),'====')
    # print sections around relevant words
    lower=text.lower()
    for term in ['forward projection algorithm','derivation','training complexity','projection matrix','target','membrane','ridge','equation','local loss','least']:
        pos=lower.find(term)
        if pos!=-1:
            print('---TERM',term,'at',pos)
            print(text[max(0,pos-1000):pos+3000])
    # also save
    Path(f'/tmp/page_stream_{si}.txt').write_text(text, encoding='utf-8')
